steps.command:
CREATE DATABASE osticket CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER 'osticket_app'@'localhost' IDENTIFIED BY 'REPLACE_WITH_UNIQUE_SECRET';
GRANT ALL PRIVILEGES ON osticket.* TO 'osticket_app'@'localhost';
SHOW GRANTS FOR 'osticket_app'@'localhost';

mariadb -h localhost -u osticket_app -p osticket
# After connecting, run:
SELECT DATABASE();
SHOW TABLES;
